sp_widget.client_script:
api.controller = function($scope, $window, $location, $rootScope) {
    /* widget controller */
    var c = this;


    var panel = $window.document.getElementsByClassName('panel-footer');

    var link = $window.document.createElement('a');

    link.setAttribute('id', 'hoc_hazard_button');
    var linkText = $window.document.createTextNode(c.data.buttonLabel + " (" + c.data.hazardCount + ")");

    link.appendChild(linkText);
    link.classList.add("hira_button", "btn", "btn-primary", "action-btn");
    if (c.data.hazardCount < 1) {
        link.href = '?id=hoc_hira_rl_form&table=x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment' +
            '&sys_id=-1&view=sp&parent=' + c.data.sys_id + '&parent_field=hira_case&query=hira_case=' + c.data.sys_id;

    } else {
        link.href = '?id=hoc_hira_rl_form&table=x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment&parent=' +
            c.data.sys_id + '&view=sp&parent_field=hira_case&sys_id=' + c.data.firstHazard;

    }

    // just in case the 'form' widget changes in upgrade
    if (panel && panel[0]) {
        panel[0].insertBefore(link, panel[0].firstChild);
    } else {
        var div = $window.document.getElementById('fallback-button-location-hoc');

        div.appendChild(link);
    }


    $rootScope.$on('spModel.gForm.env.created', function(event, gFormInstance) {
        var g_form = gFormInstance;
        var state = g_form.getValue('state');
        var button = $window.document.getElementById('hoc_hazard_button');

        if (state == '10' && button) {
            button.style.display = 'none';
        } else {
            button.style.display = 'inline-block';
        }

    });
    //if (state == '10') {
    //console.log('test');
    //}
    //});
};

sp_widget.script:
(function() {
    /* global data, $sp, GlideAggregate */
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */
    data.sys_id = $sp.getParameter('sys_id');

    data.buttonLabel = gs.getMessage('Add/View Hazards');

    var hazardCount = new GlideAggregate('x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment');

    hazardCount.addAggregate('COUNT');
    hazardCount.addQuery('hira_case', data.sys_id);
    hazardCount.query();
    while (hazardCount.next()) {
        data.hazardCount = hazardCount.getAggregate('COUNT');
    }
    var firstHazard = new GlideRecordSecure('x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment');

    firstHazard.addQuery('hira_case', data.sys_id);
    firstHazard.setLimit(1);
    firstHazard.query();
    if (firstHazard.next()) {
        data.firstHazard = firstHazard.sys_id.toString();
    } else {
        data.firstHazard = '-1';
    }
})();
